DROP TABLE IF EXISTS `conversation_rooms`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `conversation_rooms` (
  `id` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `subject` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `dateCreated` datetime DEFAULT NULL,
  `dateModified` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  `description` text COLLATE utf8_unicode_ci,
  `createdUser` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `modifiedUser` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `roomType` varchar(15) COLLATE utf8_unicode_ci NOT NULL,
  `projectId` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `createdUserName` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `modifiedUserName` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `projectName` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `issueId` varchar(36) COLLATE utf8_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `conversation_rooms_projectId` (`projectId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

