DROP TABLE IF EXISTS `memberships`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `memberships` (
  `id` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `dateCreated` datetime DEFAULT NULL,
  `createdUser` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `dateModified` datetime DEFAULT NULL,
  `modifiedUser` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `roleId` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `userId` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `createdUserName` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `modifiedUserName` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `lastActivityDate` datetime DEFAULT NULL,
  `relatedId` varchar(36) COLLATE utf8_unicode_ci DEFAULT NULL,
  `relatedTo` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `memberships_roleId` (`roleId`),
  KEY `memberships_userId` (`userId`),
  KEY `memberships_relatedId` (`relatedId`),
  KEY `memberships_relatedTo` (`relatedTo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
