  `scope` text COLLATE utf8_unicode_ci,
  `vision` text COLLATE utf8_unicode_ci,
  `createdUser` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `estimatedBudget` float DEFAULT NULL,
  `spentBudget` float DEFAULT NULL,
  `createdUserName` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `modifiedUserName` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `status` varchar(15) COLLATE utf8_unicode_ci NOT NULL,
  `done` tinyint(1) NOT NULL DEFAULT '0',
