CREATE TABLE `votes` (
  `id` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `dateCreated` datetime DEFAULT NULL,
  `dateModified` datetime DEFAULT NULL,
  `createdUser` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `createdUserName` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `modifiedUser` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `modifiedUserName` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `vote` tinyint(1) NOT NULL,
  `relatedTo` varchar(20) COLLATE utf8_unicode_ci NOT NULL,
  `relatedId` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `relatedName` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
