DROP TABLE IF EXISTS `wiki`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wiki` (
  `id` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `dateCreated` datetime DEFAULT NULL,
  `dateModified` datetime DEFAULT NULL,
  `createdUser` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `createdUserName` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `modifiedUser` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `modifiedUserName` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  `status` varchar(15) COLLATE utf8_unicode_ci NOT NULL,
  `locked` tinyint(1) NOT NULL,
  `upvotes` int(5) NOT NULL,
  `projectId` varchar(36) COLLATE utf8_unicode_ci NOT NULL,
  `markUp` text COLLATE utf8_unicode_ci NOT NULL,
  `parentId` varchar(36) COLLATE utf8_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
