CREATE DEFINER=`nouman`@`localhost` FUNCTION `checkActivityIsLatest`(userId VARCHAR(36), activityId VARCHAR(36)) RETURNS int(1)
    DETERMINISTIC
RETURN (SELECT IF(COUNT(t2.id) = 1,1,0) as temp from
                                (select * from 
                                (select a.id from users u left join activities a on a.createdUser = u.id where u.id = userId
                                ORDER BY a.dateCreated
                                DESC LIMIT 5) t
                            where t.id = activityId) t2) ;;
