CREATE DEFINER=`nouman`@`localhost` FUNCTION `checkProjectIsLatest`(userId VARCHAR(36), projectId VARCHAR(36)) RETURNS int(1)
    DETERMINISTIC
RETURN (select CASE WHEN t2.t IS NULL THEN 0 ELSE t2.t END AS r
from (select CASE WHEN t.id =projectId THEN 1 ELSE 0 END AS t from (select p.id from projects p left join memberships m on m.projectId = p.id
left join activities a2 on a2.relatedId = p.id and a2.relatedTo = 'project'
where m.userId = userId
GROUP BY CONCAT(m.userId, p.id)
ORDER BY a2.dateCreated DESC LIMIT 5) t  where t.id = projectId) as t2) ;;
DELIMITER ;
