CREATE DEFINER=`nouman`@`localhost` FUNCTION `checkUserWorkWithOthers`(userId1 VARCHAR(36), userId2 VARCHAR(36)) RETURNS int(1)
    DETERMINISTIC
RETURN (SELECT IF(COUNT(t2.userId) = 1,1,0) as temp from
(select userId from (select m2.userId,COUNT(m2.id) as occurenceOfUser from projects p 
inner join memberships m on m.projectId = p.id
inner join memberships m2 on m2.projectId = m.projectId  AND m2.userId != userId1
left join users u on u.id = m2.userId 
where m.userId = userId1
GROUP BY m2.userId 
ORDER BY occurenceOfUser DESC LIMIT 3) t
where t.userId = userId2) t2 ) ;;
DELIMITER ;
