CREATE DEFINER=`nouman`@`localhost` PROCEDURE `test_p`()
BEGIN
select * from (
SELECT 
    @row_number:=CASE
        WHEN @userId = Activity.createdUser 
THEN @row_number + 1
        ELSE 1
    END AS rank,
    @userId:=Activity.createdUser,
    Activity.*
FROM
    activities Activity
ORDER BY Activity.createdUser) topActivities
where topActivities.rank <= 5;
END ;;
DELIMITER ;
